script:
function process(ctx) {
    var vars = ctx.vars || {};
    // 颜色必须使用六位十六进制，例如 #FFF2CC；背景色留空表示不启用。
    var dialogColor = color(vars.dialogColor, "#9D5960");
    var narrationColor = color(vars.narrationColor, "#274B5A");
    var percentColor = color(vars.percentColor, "#4F6FAE");
    var dialogBackground = color(vars.dialogBackground, "");
    var narrationBackground = color(vars.narrationBackground, "");
    var percentBackground = color(vars.percentBackground, "");
    var specialMarker = String.fromCharCode(0xE000) + "LEGADO_SPECIAL_";

    // 支持中文直角引号、双层引号、单双弯引号和英文引号。
    // 扫描时使用栈：嵌套引号只把最外层作为对话整体处理。
    var quoteClose = {
        "“": "”",
        "‘": "’",
        "「": "」",
        "『": "』",
        "﹁": "﹂",
        "﹃": "﹄",
        "〝": "〞",
        "\"": "\"",
        "'": "'"
    };

    function color(value, fallback) {
        var text = value == null ? "" : String(value).replace(/^\s+|\s+$/g, "");
        if (text === "" && fallback === "") return "";
        return /^#[0-9a-fA-F]{6}$/.test(text) ? text : fallback;
    }

    function enabled(value) {
        var text = value == null ? "" : String(value).replace(/^\s+|\s+$/g, "").toLowerCase();
        return text === "true" || text === "1" || text === "yes" || text === "on" || text === "是";
    }

    function sizeTag(value) {
        var text = value == null ? "" : String(value).replace(/^\s+|\s+$/g, "").toLowerCase();
        if (text === "small" || text === "小") return ["<small>", "</small>"];
        if (text === "big" || text === "large" || text === "大") return ["<big>", "</big>"];
        if (text === "x-large" || text === "xlarge" || text === "超大") return ["<font size=\"5\">", "</font>"];
        return ["", ""];
    }

    function isHighSurrogate(code) {
        return code >= 0xD800 && code <= 0xDBFF;
    }

    function isLowSurrogate(code) {
        return code >= 0xDC00 && code <= 0xDFFF;
    }

    // HTML 解析器对部分四字节符号/emoji 的直接字符串处理不稳定。
    // 将成对代理项转成数字实体，避免符号被替换成 �；普通文字保持原样。
    function escapeHtml(value) {
        var source = String(value);
        var output = [];
        var i;
        for (i = 0; i < source.length; i++) {
            var code = source.charCodeAt(i);
            if (isHighSurrogate(code) && i + 1 < source.length) {
                var low = source.charCodeAt(i + 1);
                if (isLowSurrogate(low)) {
                    var codePoint = (code - 0xD800) * 0x400 + (low - 0xDC00) + 0x10000;
                    output.push("&#x" + codePoint.toString(16).toUpperCase() + ";");
                    i++;
                    continue;
                }
            }
            if (code === 38) output.push("&amp;");
            else if (code === 60) output.push("&lt;");
            else if (code === 62) output.push("&gt;");
            else if (code === 34) output.push("&quot;");
            else if (code === 39) output.push("&#39;");
            else output.push(source.charAt(i));
        }
        return output.join("");
    }

    function isWordChar(value) {
        return value != null && /[A-Za-z0-9_]/.test(value);
    }

    function isApostropheInWord(text, index) {
        return text.charAt(index) === "'" &&
            isWordChar(text.charAt(index - 1)) &&
            isWordChar(text.charAt(index + 1));
    }

    // 只返回最外层、完整闭合的引号范围。
    // 例如：
    // “楼主这“懂点常识”真可怕。” → 整句作为一个范围；
    // “他说“甲”，又说“乙”。” → 最外层整句作为一个范围。
    function findOutermostQuotes(text) {
        var stack = [];
        var ranges = [];
        var i;
        for (i = 0; i < text.length; i++) {
            var current = text.charAt(i);
            if (current === "'" && isApostropheInWord(text, i)) continue;
            // 对称引号（英文单/双引号）必须先判断闭合，再判断开始，
            // 否则结束引号会被再次压入栈，导致范围无法完成。
            if (stack.length > 0 && current === stack[stack.length - 1].close) {
                var item = stack.pop();
                if (stack.length === 0) {
                    ranges.push({ start: item.start, end: i + 1 });
                }
                continue;
            }
            if (quoteClose[current] != null) {
                stack.push({ open: current, close: quoteClose[current], start: i });
            }
        }
        return ranges;
    }

    function applyStyle(text, colorValue, backgroundValue, bold, italic, underline, strike, size) {
        var html = text;
        var fontSize = sizeTag(size);
        if (fontSize[0] !== "") html = fontSize[0] + html + fontSize[1];
        if (strike) html = "<s>" + html + "</s>";
        if (underline) html = "<u>" + html + "</u>";
        if (italic) html = "<i>" + html + "</i>";
        if (bold) html = "<b>" + html + "</b>";
        if (backgroundValue !== "") {
            var bgTag = "epubbg" + backgroundValue.substring(1);
            html = "<" + bgTag + ">" + html + "</" + bgTag + ">";
        }
        if (colorValue !== "") html = '<font color="' + colorValue + '">' + html + "</font>";
        return html;
    }

    function renderStyled(text, colorValue, backgroundValue, prefix) {
        return applyStyle(
            escapeHtml(text),
            colorValue,
            backgroundValue,
            enabled(vars[prefix + "Bold"]),
            enabled(vars[prefix + "Italic"]),
            enabled(vars[prefix + "Underline"]),
            enabled(vars[prefix + "Strike"]),
            vars[prefix + "Size"]
        );
    }

    function renderPlain(text) {
        var output = [];
        var last = 0;
        var match;
        var percentPattern = /(\d+(?:\.\d+)?%)/g;
        percentPattern.lastIndex = 0;
        while ((match = percentPattern.exec(text)) !== null) {
            output.push(renderStyled(text.substring(last, match.index), narrationColor, narrationBackground, "narration"));
            output.push(renderStyled(match[0], percentColor, percentBackground, "percent"));
            last = percentPattern.lastIndex;
        }
        output.push(renderStyled(text.substring(last), narrationColor, narrationBackground, "narration"));
        return output.join("");
    }

    function renderParagraph(text) {
        // 图片、已有 HTML、分页标记等内容由软件保护，不能再次包裹。
        if (text.indexOf(specialMarker) >= 0) return text;

        var ranges = findOutermostQuotes(text);
        var output = [];
        var last = 0;
        var i;
        for (i = 0; i < ranges.length; i++) {
            var range = ranges[i];
            output.push(renderPlain(text.substring(last, range.start)));
            // 一次渲染完整的最外层范围，内部引号不会再次改变颜色。
            output.push(renderStyled(text.substring(range.start, range.end), dialogColor, dialogBackground, "dialog"));
            last = range.end;
        }
        output.push(renderPlain(text.substring(last)));
        return "<usehtml>" + output.join("") + "</usehtml>";
    }

    return ctx.paragraphs.map(function(paragraph) {
        if (!paragraph || paragraph.text == null || String(paragraph.text).replace(/^\s+|\s+$/g, "") === "") {
            return null;
        }
        return {
            index: paragraph.index,
            text: renderParagraph(String(paragraph.text))
        };
    });
}
